SET statement_timeout = 0
SET lock_timeout = 0
SET idle_in_transaction_session_timeout = 0
SET client_encoding = 'UTF8'
SET standard_conforming_strings = on
SELECT pg_catalog.set_config('search_path', '', false)
SET check_function_bodies = false
SET xmloption = content
SET client_min_messages = warning
SET row_security = off
SET default_tablespace = ''
SET default_table_access_method = heap
drop role if exists m_app
drop role if exists m_anon
create extension if not exists "uuid-ossp" with schema public
create extension if not exists citext
create extension if not exists hstore
create extension if not exists ltree
create extension if not exists btree_gin
create extension if not exists btree_gist
create extension if not exists pg_trgm
create extension if not exists pg_stat_statements
create extension if not exists tablefunc
create extension if not exists intarray
comment on extension citext is 'case-insensitive text'
create type m_status as enum ('active', 'paused', 'closed')
create type m_addr as (street text, city text, zip varchar(10))
create domain m_email as citext check (value ~ '^[^@]+@[^@]+$')
create domain m_pos as integer check (value > 0)
create type m_floatrange as range (subtype = float8)
create table m_users (id uuid default uuid_generate_v4() not null, email m_email not null, name text, status m_status default 'active'::m_status not null, prefs jsonb default '{}'::jsonb not null, tags text[] default '{}'::text[] not null, addr m_addr, attrs hstore, path ltree, created_at timestamp(6) without time zone not null default now(), updated_at timestamptz default timezone('utc'::text, now()) not null, balance numeric(12,2) default 0 not null, born date, active boolean default true, login_count integer default 0 not null, ip inet, search tsvector generated always as (to_tsvector('english', coalesce(name, ''))) stored)
alter table only m_users add constraint m_users_pkey primary key (id)
alter table only m_users add constraint m_users_email_key unique (email)
create table m_orgs (id bigint generated by default as identity primary key, slug citext unique not null, name text not null, plan text default 'free' check (plan in ('free', 'pro', 'enterprise')), meta jsonb, period tstzrange, created_at timestamptz default now())
create table m_members (org_id bigint not null references m_orgs(id) on delete cascade, user_id uuid not null references m_users(id) on delete cascade deferrable initially deferred, role text not null default 'member', joined date default current_date, primary key (org_id, user_id))
create table m_events (id bigserial, org_id bigint not null, kind text not null, payload jsonb not null default '{}', at timestamptz not null default now(), amount money, bits bit(8), dur interval, t time with time zone, primary key (id, at)) partition by range (at)
create table m_events_2026 partition of m_events for values from ('2026-01-01') to ('2027-01-01')
create table m_events_default partition of m_events default
create table m_days (day date primary key, total numeric not null default 0)
create table m_prices (sku text, valid daterange, price numeric(10,2), exclude using gist (sku with =, valid with &&))
create table m_ledger (id numeric(20,0) primary key, memo text)
create table m_flags (enabled boolean primary key, note text)
create table m_ts (at timestamptz primary key, v double precision)
create table m_kv (k m_status primary key, v text)
create table m_scores (score double precision primary key, who text)
create table m_slots (at time primary key, what text)
create unlogged table m_cache (k text primary key, v bytea, expires timestamptz)
create table m_audit (id bigint generated always as identity, tbl regclass, row_id text, old jsonb, new jsonb, who name default current_user, at timestamptz default clock_timestamp())
create sequence m_ticket_seq start with 1000 increment by 1 no minvalue no maxvalue cache 1
create table m_tickets (id integer default nextval('m_ticket_seq'::regclass) not null primary key, code text generated always as ('T-' || id::text) stored, title varchar(200) not null)
alter sequence m_ticket_seq owned by m_tickets.id
create index m_users_prefs_idx on m_users using gin (prefs)
create index m_users_prefs_path_idx on m_users using gin (prefs jsonb_path_ops)
create index m_users_tags_idx on m_users using gin (tags)
create index m_users_search_idx on m_users using gin (search)
create index m_users_name_trgm on m_users using gin (name gin_trgm_ops)
create index m_users_lower_email on m_users (lower(email::text))
create unique index m_users_active_email on m_users (email) where active
create index m_users_created_brin on m_users using brin (created_at)
create index m_users_path_gist on m_users using gist (path)
create index m_users_attrs_idx on m_users using gin (attrs)
create index m_events_org_at on m_events (org_id, at desc nulls last) include (kind)
create index m_orgs_period on m_orgs using gist (period)
create index concurrently m_users_name_idx on m_users (name text_pattern_ops)
create index m_users_hash on m_users using hash (name)
create function m_touch() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$
create trigger m_users_touch before update on m_users for each row execute function m_touch()
create function m_audit_fn() returns trigger language plpgsql security definer set search_path = public as $$ begin if tg_op = 'DELETE' then insert into m_audit (tbl, row_id, old) values (tg_relid::regclass, old.id::text, to_jsonb(old)); return old; end if; insert into m_audit (tbl, row_id, new) values (tg_relid::regclass, new.id::text, to_jsonb(new)); return new; end; $$
create trigger m_users_audit after insert or update or delete on m_users for each row execute function m_audit_fn()
create function m_slug(t text) returns text language sql immutable strict parallel safe as $$ select lower(regexp_replace(trim(t), '[^a-zA-Z0-9]+', '-', 'g')) $$
create or replace function m_org_count(uid uuid) returns integer language sql stable as $$ select count(*)::int from m_members where user_id = uid $$
create function m_users_of(o bigint) returns setof m_users language sql stable as $$ select u.* from m_users u join m_members m on m.user_id = u.id where m.org_id = o $$
create function m_stats(out total bigint, out active bigint) language sql as $$ select count(*), count(*) filter (where active) from m_users $$
create procedure m_cleanup(days integer) language plpgsql as $$ begin delete from m_cache where expires < now() - make_interval(days => days); commit; end; $$
create aggregate m_concat(text) (sfunc = textcat, stype = text, initcond = '')
create function m_ddl() returns event_trigger language plpgsql as $$ begin null; end $$
create event trigger m_ddl_trg on ddl_command_end execute function m_ddl()
drop event trigger m_ddl_trg
create view m_active_users as select id, email, name from m_users where active
create view m_user_orgs with (security_invoker = true) as select u.id, u.email, o.slug from m_users u join m_members m on m.user_id = u.id join m_orgs o on o.id = m.org_id
create materialized view m_org_sizes as select org_id, count(*) as members from m_members group by org_id with no data
create unique index m_org_sizes_idx on m_org_sizes (org_id)
refresh materialized view m_org_sizes
create or replace view m_recent as select * from m_events where at > now() - interval '7 days' with local check option
create role m_app nologin
create role m_anon nologin
alter table m_users enable row level security
alter table m_users force row level security
create policy m_users_self on m_users for select to m_app using (id = nullif(current_setting('request.jwt.claim.sub', true), '')::uuid)
create policy m_users_upd on m_users as permissive for update to m_app using (true) with check (active)
alter table m_users no force row level security
grant usage on schema public to m_app, m_anon
grant select, insert, update, delete on all tables in schema public to m_app
grant usage, select on all sequences in schema public to m_app
grant execute on function m_slug(text) to m_anon
alter default privileges in schema public grant select on tables to m_anon
revoke all on m_audit from public
comment on table m_users is 'application users'
comment on column m_users.email is 'login email'
comment on function m_slug(text) is 'slugify'
comment on type m_status is 'lifecycle'
alter type m_status add value if not exists 'archived' after 'closed'
alter table m_users add column nickname varchar(50) collate "C"
alter table m_users alter column login_count type bigint using login_count::bigint
alter table m_users rename column nickname to handle
alter table m_users add constraint m_users_balance_nonneg check (balance >= 0) not valid
alter table m_users validate constraint m_users_balance_nonneg
alter table m_members add constraint m_members_role_chk check (role = any (array['owner'::text, 'admin'::text, 'member'::text]))
alter table m_orgs add constraint m_orgs_slug_len check (char_length(slug::text) >= 2)
alter table m_tickets add constraint m_tickets_title_uniq unique (title) deferrable initially immediate
alter table m_events replica identity full
alter table m_users set (autovacuum_vacuum_scale_factor = 0.05)
alter table m_users cluster on m_users_pkey
create publication m_pub for table m_users, m_orgs
create statistics m_stat (dependencies) on org_id, kind from m_events
create rule m_no_delete as on delete to m_days do instead nothing
create schema if not exists m_private authorization m_app
create table m_private.secrets (id uuid primary key default gen_random_uuid(), v text)
create collation m_ci (provider = icu, locale = 'und-u-ks-level2', deterministic = false)
create table m_ci_t (name text collate m_ci unique)
insert into m_orgs (slug, name, period) values ('Acme', 'Acme Inc', '[2026-01-01, 2027-01-01)')
insert into m_users (email, name, tags, prefs, attrs, path, addr, ip) values ('A@x.io', 'Ada', array['a','b'], '{"theme":"dark","n":1}', 'k=>v', 'top.sci', row('1 Main', 'Pune', '411001'), '10.0.0.1')
insert into m_members (org_id, user_id) select 1, id from m_users
select email = 'a@x.io', name, status, tags, balance, active, login_count, ip from m_users
select prefs->>'theme', prefs @> '{"n":1}', prefs ? 'theme', prefs #>> '{theme}', jsonb_set(prefs, '{n}', '2') from m_users
select (addr).city, attrs -> 'k', path <@ 'top', tags && array['a'], tags @> array['b'], array_length(tags, 1), cardinality(tags) from m_users
select name from m_users where prefs['theme'] = '"dark"'
select unnest(tags) from m_users
select o.slug, count(m.*) from m_orgs o left join m_members m on m.org_id = o.id group by o.slug
insert into m_events (org_id, kind, payload, at, amount, bits, dur, t) values (1, 'x', '{}', '2026-06-01', '12.50', B'10101010', '1 day 2 hours', '10:00+05:30') returning id, amount, bits, dur, t
select date_trunc('month', at), count(*), sum(amount) from m_events group by 1 order by 1
insert into m_days values ('2026-01-01', 5) on conflict (day) do update set total = m_days.total + excluded.total returning *
insert into m_days values ('2026-01-01', 5) on conflict (day) do update set total = m_days.total + excluded.total returning *
insert into m_ledger values (12345678901234567890, 'big') returning id
insert into m_ts values ('2026-01-01 00:00+00', 1.5), ('2026-01-02 00:00+00', 2.5)
select * from m_ts where at >= '2026-01-02' order by at
insert into m_flags values (true, 'on'), (false, 'off')
insert into m_kv values ('paused', 'p'), ('active', 'a')
select k, v from m_kv order by k
insert into m_scores values (1.5, 'a'), (0.5, 'b')
select * from m_scores order by score
insert into m_slots values ('09:00', 'standup'), ('08:30', 'coffee')
select * from m_slots order by at
insert into m_prices values ('a', '[2026-01-01,2026-02-01)', 10)
insert into m_prices values ('a', '[2026-01-15,2026-03-01)', 12)
insert into m_tickets (title) values ('first'), ('second') returning id, code
update m_users set prefs = prefs || '{"x":true}' where email = 'a@x.io' returning updated_at is not null, prefs
select count(*) from m_audit
select m_slug(' Hello World '), m_org_count((select id from m_users limit 1)), (m_stats()).total
call m_cleanup(7)
select email from m_users_of(1)
select m_concat(name) from m_users
select * from m_active_users
select email, slug from m_user_orgs
select * from m_org_sizes
with recursive t(n) as (values (1) union all select n + 1 from t where n < 5) select sum(n) from t
select string_agg(name, ', ' order by name), array_agg(distinct name), json_build_object('n', count(*)) from m_users
select row_to_json(row(slug, name)) from m_orgs
select percentile_cont(0.5) within group (order by v), mode() within group (order by v) from m_ts
select at, sum(v) over (order by at rows between unbounded preceding and current row), lag(v) over w, ntile(2) over w from m_ts window w as (order by at)
select count(*) from m_ts tablesample bernoulli (100)
select pg_advisory_xact_lock(hashtext('x'))
select extract(epoch from interval '1 hour'), age(timestamp '2026-01-01', timestamp '2025-01-01'), make_date(2026, 1, 2), date_part('dow', date '2026-10-14')
select pg_size_pretty(pg_total_relation_size('m_users')) is not null, pg_relation_size('m_users') >= 0
select obj_description('m_users'::regclass), col_description('m_users'::regclass, 2)
select format('%I.%I', 'a b', 'c'), quote_ident('x y'), quote_literal('it''s'), encode(sha256('abc'::bytea), 'hex'), md5('x'), gen_random_uuid() is not null
select regexp_split_to_array('a,b', ','), string_to_array('a-b', '-'), split_part('a.b', '.', 2), translate('abc', 'ab', 'xy'), initcap('hello world'), left('abc', 2), reverse('abc')
select '{"a":[1,2]}'::jsonb #> '{a,1}', jsonb_path_query('{"a":[1,2]}', '$.a[*] ? (@ > 1)'), jsonb_strip_nulls('{"a":null}'), jsonb_typeof('1')
select width_bucket(5, 0, 10, 5), round(2.5), trunc(2.567, 2), 7 / 2, 7 % 2, power(2, 10), sqrt(16), ceil(1.2), greatest(1, 2), random() < 1
select '2026-01-01'::date + 30, '2026-01-31'::date + interval '1 month', date_trunc('week', timestamp '2026-10-14'), (timestamp '2026-10-14 10:00' at time zone 'UTC') at time zone 'America/New_York'
select table_name, table_type from information_schema.tables where table_schema = 'public' and table_name like 'm\_%' order by table_name
select indexname from pg_indexes where tablename = 'm_users' order by 1
select conname, contype, pg_get_constraintdef(oid) from pg_constraint where conrelid = 'm_users'::regclass order by 1
select pg_get_viewdef('m_active_users'::regclass, true)
select pg_get_indexdef('m_users_lower_email'::regclass)
select attname, format_type(atttypid, atttypmod) from pg_attribute where attrelid = 'm_users'::regclass and attnum > 0 and not attisdropped order by attnum
select enumlabel from pg_enum e join pg_type t on t.oid = e.enumtypid where t.typname = 'm_status' order by enumsortorder
select c.relname, c.relkind from pg_class c where c.relname like 'm\_events%' order by 1
select column_name, column_default, is_nullable, data_type from information_schema.columns where table_name = 'm_orgs' order by ordinal_position
delete from m_users where email = 'a@x.io'
select count(*) from m_members
